SELECT run_id
  FROM public.agent_runtime_execution_runs
 WHERE tenant_id = #{tenantId}
   AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND session_id = #{sessionId}
   AND end_user_id = #{endUserId}
   AND status IN ('QUEUED', 'RUNNING', 'SUSPENDED', 'RESUMING')
 ORDER BY run_id

