UPDATE public.agent_runtime_sessions
   SET status = #{targetStatus},
       session_revision = #{outputRevision},
       updated_epoch_second = #{updatedEpochSecond},
       updated_nano = #{updatedNano}
 WHERE tenant_id = #{tenantId} AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND session_id = #{sessionId} AND end_user_id = #{endUserId}
   AND status = #{expectedStatus}
   AND session_revision = #{expectedRevision}

mapper.select:
SELECT tenant_id, session_id, target_kind, target_id, end_user_id,
       expected_status, target_status, expected_revision,
       causation_input_id, command_fingerprint, command_data,
       output_status, output_revision,
       output_updated_epoch_second, output_updated_nano
  FROM public.agent_runtime_session_mutations
 WHERE tenant_id = #{tenantId} AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND session_id = #{sessionId} AND end_user_id = #{endUserId}
   AND expected_status = #{expectedStatus}
   AND target_status = #{targetStatus}
   AND expected_revision = #{expectedRevision}
   AND causation_input_id = #{causationInputId}
